import Image from 'next/image'
import Link from 'next/link'
import { ArrowUpRight } from 'lucide-react'

import { cn } from '@/lib/utils'

export type AboutMetricsSectionProps = {
  eyebrow?: string
  title: string
  paragraphs: readonly string[]
  metrics: readonly { value: string; label: string }[]
  image?: { src: string; alt: string }
  action?: { label: string; href: string }
  mediaPosition?: 'left' | 'right'
  className?: string
}

export function AboutMetricsSection({
  eyebrow,
  title,
  paragraphs,
  metrics,
  image,
  action,
  mediaPosition = 'right',
  className,
}: AboutMetricsSectionProps) {
  return (
    <section className={cn('overflow-hidden bg-white py-20 md:py-28', className)}>
      <div className="container grid items-center gap-14 lg:grid-cols-[1.12fr_.88fr] lg:gap-20">
        <div className={cn(mediaPosition === 'left' && 'lg:order-2')}>
          {eyebrow ? (
            <p className="text-xs font-bold uppercase tracking-[0.24em] text-[#752871]">
              {eyebrow}
            </p>
          ) : null}
          <h2 className="mt-4 text-3xl font-bold tracking-tight text-[#10100e] md:text-5xl">
            {title}
          </h2>
          <div className="mt-7 space-y-5">
            {paragraphs.map((paragraph, index) => (
              <p key={`${paragraph.slice(0, 24)}-${index}`} className="leading-8 text-[#5a5560]">
                {paragraph}
              </p>
            ))}
          </div>

          <dl className="mt-10 grid grid-cols-2 gap-6 border-y border-[#e8e4ea] py-7 sm:grid-cols-3">
            {metrics.slice(0, 3).map((metric) => (
              <div key={`${metric.value}-${metric.label}`}>
                <dd className="text-3xl font-bold text-[#752871] md:text-4xl">{metric.value}</dd>
                <dt className="mt-1 text-xs uppercase tracking-wider text-[#7a7480]">
                  {metric.label}
                </dt>
              </div>
            ))}
          </dl>

          {action ? (
            <Link
              href={action.href}
              className="mt-8 inline-flex items-center gap-2 font-semibold text-[#752871]"
            >
              {action.label}
              <ArrowUpRight className="h-4 w-4" aria-hidden />
            </Link>
          ) : null}
        </div>

        <div className={cn('relative min-h-[520px]', mediaPosition === 'left' && 'lg:order-1')}>
          <div className="absolute inset-4 rotate-3 rounded-[3rem] bg-[#752871]/15" />
          <figure className="absolute inset-0 overflow-hidden rounded-[3rem] bg-[#3f2644] shadow-xl">
            {image ? (
              <Image
                src={image.src}
                alt={image.alt}
                fill
                className="object-cover"
                sizes="(min-width: 1024px) 40vw, 90vw"
              />
            ) : (
              <div className="relative h-full overflow-hidden">
                <span className="absolute -left-16 top-12 h-72 w-72 rounded-[45%_55%_40%_60%] bg-[#752871]" />
                <span className="absolute -right-12 bottom-10 h-64 w-64 rounded-[60%_40%] bg-[#9b4b96]" />
                <span className="absolute left-1/2 top-1/2 h-44 w-44 -translate-x-1/2 -translate-y-1/2 rounded-full border-[24px] border-white/20" />
              </div>
            )}
          </figure>
        </div>
      </div>
    </section>
  )
}

'use client'

import Image from 'next/image'
import { useEffect, useRef, useState } from 'react'
import { animate, motion, useInView, useReducedMotion } from 'framer-motion'
import { cn } from '@/lib/utils'

export type CredibilityStat = { value: number; suffix?: string; label: string }
export type CredibilityReason = { title: string; description: string }

export type CredibilitySectionProps = {
  title: string
  description?: string
  stats?: CredibilityStat[]
  reasons: CredibilityReason[]
  image?: { src: string; alt: string }
  caption?: string
  className?: string
}

function CountUp({ value, suffix = '' }: { value: number; suffix?: string }) {
  const ref = useRef<HTMLSpanElement>(null)
  const inView = useInView(ref, { once: true })
  const reduceMotion = useReducedMotion()
  const [display, setDisplay] = useState(reduceMotion ? value : 0)

  useEffect(() => {
    if (!inView || reduceMotion) return
    const controls = animate(0, value, {
      duration: 1.6,
      ease: 'easeOut',
      onUpdate: (latest) => setDisplay(Math.round(latest)),
    })
    return () => controls.stop()
  }, [inView, reduceMotion, value])

  return (
    <span ref={ref} className="tabular-nums">
      {display}
      {suffix}
    </span>
  )
}

export function CredibilitySection({
  title,
  description,
  stats = [],
  reasons,
  image,
  caption,
  className,
}: CredibilitySectionProps) {
  const reduceMotion = useReducedMotion()

  return (
    <section className={cn('py-16 md:py-24', className)}>
      <div className="container">
        <div className="max-w-3xl">
          <h2 className="text-3xl font-bold tracking-tight md:text-4xl">{title}</h2>
          {description ? (
            <p className="mt-4 text-lg leading-8 text-muted-foreground">{description}</p>
          ) : null}
        </div>

        {stats.length ? (
          <dl className="mt-10 grid gap-6 border-y py-8 sm:grid-cols-3">
            {stats.map((stat) => (
              <div key={stat.label}>
                <dt className="sr-only">{stat.label}</dt>
                <dd className="text-5xl font-bold text-primary">
                  <CountUp value={stat.value} suffix={stat.suffix} />
                </dd>
                <dd className="mt-2 text-sm font-medium text-muted-foreground">{stat.label}</dd>
              </div>
            ))}
          </dl>
        ) : null}

        <div className={cn('mt-12 grid gap-10', image && 'lg:grid-cols-[0.8fr_1.2fr]')}>
          {image ? (
            <figure className="lg:sticky lg:top-24 lg:self-start">
              <div className="relative aspect-[4/5] overflow-hidden rounded-3xl bg-muted">
                <Image
                  src={image.src}
                  alt={image.alt}
                  fill
                  className="object-cover"
                  sizes="(min-width: 1024px) 35vw, 100vw"
                />
              </div>
              {caption ? (
                <figcaption className="mt-3 text-sm text-muted-foreground">{caption}</figcaption>
              ) : null}
            </figure>
          ) : null}
          <ol className="grid gap-px overflow-hidden rounded-3xl border bg-border sm:grid-cols-2">
            {reasons.map((reason, index) => (
              <motion.li
                key={reason.title}
                initial={reduceMotion ? false : { opacity: 0, y: 20 }}
                whileInView={{ opacity: 1, y: 0 }}
                viewport={{ once: true, amount: 0.4 }}
                transition={{ duration: 0.45, delay: (index % 2) * 0.1 }}
                className="group bg-background p-6 transition hover:bg-primary/5"
              >
                <span className="font-mono text-sm font-bold text-primary transition group-hover:tracking-widest">
                  {String(index + 1).padStart(2, '0')}
                </span>
                <h3 className="mt-3 text-lg font-semibold">{reason.title}</h3>
                <p className="mt-2 text-sm leading-6 text-muted-foreground">{reason.description}</p>
              </motion.li>
            ))}
          </ol>
        </div>
      </div>
    </section>
  )
}

'use client'

import Image from 'next/image'
import { A11y, Autoplay } from 'swiper/modules'
import { Swiper, SwiperSlide } from 'swiper/react'

import { EyebrowHeading } from '@/components/library/primitives/EyebrowHeading'
import { getAccentTone, type AccentTone } from '@/components/library/primitives/accentTones'
import { useReducedMotion } from '@/components/library/motion/useReducedMotion'
import { cn } from '@/lib/utils'

import 'swiper/css'

export type LogoCarouselBandLogo = {
  name: string
  src: string
  href?: string
}

export type LogoCarouselBandProps = {
  logos: readonly LogoCarouselBandLogo[]
  title?: string
  eyebrow?: string
  description?: string
  monochrome?: boolean
  autoplayDelay?: number
  tone?: AccentTone
  className?: string
}

/** Faixa de logos em carrossel contínuo com divisórias e realce no hover. */
export function LogoCarouselBand({
  logos,
  title,
  eyebrow,
  description,
  monochrome = true,
  autoplayDelay = 2200,
  tone = 'glow',
  className,
}: LogoCarouselBandProps) {
  const t = getAccentTone(tone)
  const reduced = useReducedMotion()
  const light = tone === 'industrial'
  const items = logos.length < 8 ? [...logos, ...logos] : logos

  return (
    <section className={cn('relative overflow-hidden', t.section, className)}>
      <div className="container py-14 lg:py-16">
        {title ? (
          <EyebrowHeading
            tone={tone}
            eyebrow={eyebrow}
            title={title}
            description={description}
            layout="split"
            className="mb-10 lg:mb-12"
          />
        ) : null}

        <div
          className={cn(
            'overflow-hidden border',
            t.border,
            t.panel,
            tone === 'glow' && 'rounded-md',
          )}
        >
          <Swiper
            modules={[A11y, Autoplay]}
            spaceBetween={0}
            slidesPerView={2}
            loop
            speed={800}
            autoplay={reduced ? false : { delay: autoplayDelay, disableOnInteraction: false }}
            breakpoints={{
              640: { slidesPerView: 3 },
              768: { slidesPerView: 4 },
              1024: { slidesPerView: 6 },
            }}
          >
            {items.map((logo, index) => {
              const content = (
                <Image
                  src={logo.src}
                  alt={logo.name}
                  width={140}
                  height={64}
                  className={cn(
                    'max-h-12 w-auto object-contain opacity-70 transition-all duration-500 group-hover:opacity-100',
                    monochrome &&
                      (light ? 'grayscale group-hover:grayscale-0' : 'brightness-0 invert'),
                  )}
                />
              )
              return (
                <SwiperSlide key={`${logo.name}-${index}`}>
                  <div
                    className={cn(
                      'group flex h-28 items-center justify-center border-l px-6 transition-colors duration-300',
                      t.border,
                      light ? 'hover:bg-slate-50' : 'hover:bg-white/5',
                    )}
                  >
                    {logo.href ? (
                      <a
                        href={logo.href}
                        target="_blank"
                        rel="noopener noreferrer"
                        aria-label={logo.name}
                        className={t.focus}
                      >
                        {content}
                      </a>
                    ) : (
                      content
                    )}
                  </div>
                </SwiperSlide>
              )
            })}
          </Swiper>
        </div>
      </div>
    </section>
  )
}

import { Check } from 'lucide-react'
import { cn } from '@/lib/utils'

export type ProcessStepsProps = {
  title: string
  description?: string
  steps: Array<{ title: string; description: string }>
  className?: string
}

export function ProcessSteps({ title, description, steps, className }: ProcessStepsProps) {
  return (
    <section
      className={cn('bg-muted/30 py-16 md:py-24', className)}
      aria-labelledby="process-title"
    >
      <div className="container">
        <div className="max-w-2xl">
          <h2 id="process-title" className="text-3xl font-bold tracking-tight md:text-4xl">
            {title}
          </h2>
          {description ? <p className="mt-4 text-lg text-muted-foreground">{description}</p> : null}
        </div>
        <ol className="mt-10 grid gap-5 md:grid-cols-2 lg:grid-cols-4">
          {steps.map((step, index) => (
            <li
              key={step.title}
              className="relative rounded-2xl border bg-background p-6 shadow-sm"
            >
              <span className="flex h-10 w-10 items-center justify-center rounded-full bg-primary font-bold text-primary-foreground">
                {index + 1}
              </span>
              <h3 className="mt-5 text-lg font-semibold">{step.title}</h3>
              <p className="mt-2 text-sm leading-6 text-muted-foreground">{step.description}</p>
              {index === steps.length - 1 ? (
                <Check className="absolute right-5 top-5 h-5 w-5 text-primary" aria-hidden="true" />
              ) : null}
            </li>
          ))}
        </ol>
      </div>
    </section>
  )
}

'use client'

import Image from 'next/image'
import Link from 'next/link'
import { motion, useReducedMotion } from 'framer-motion'
import { Globe, Instagram, Linkedin, Mail, MessageCircle, type LucideIcon } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { cn } from '@/lib/utils'

export type TeamSocialType = 'linkedin' | 'instagram' | 'email' | 'whatsapp' | 'website'

export type TeamSectionMember = {
  name: string
  role: string
  image: { src: string; alt?: string }
  bio?: string
  socials?: Array<{ type: TeamSocialType; href: string }>
}

export type TeamSectionProps = {
  title: string
  eyebrow?: string
  description?: string
  members: TeamSectionMember[]
  variant?: 'overlay' | 'cards' | 'minimal' | 'featured'
  columns?: 3 | 4
  action?: { label: string; href: string }
  className?: string
}

const socialMeta: Record<TeamSocialType, { icon: LucideIcon; label: string }> = {
  linkedin: { icon: Linkedin, label: 'LinkedIn' },
  instagram: { icon: Instagram, label: 'Instagram' },
  email: { icon: Mail, label: 'E-mail' },
  whatsapp: { icon: MessageCircle, label: 'WhatsApp' },
  website: { icon: Globe, label: 'Site' },
}

const columnClasses = {
  3: 'sm:grid-cols-2 lg:grid-cols-3',
  4: 'sm:grid-cols-2 lg:grid-cols-4',
}

function socialHref(type: TeamSocialType, href: string) {
  if (type === 'email' && !href.startsWith('mailto:')) return `mailto:${href}`
  return href
}

function Socials({
  member,
  tone = 'default',
  className,
}: {
  member: TeamSectionMember
  tone?: 'default' | 'inverted'
  className?: string
}) {
  if (!member.socials?.length) return null

  return (
    <ul className={cn('flex flex-wrap gap-2', className)}>
      {member.socials.map((social) => {
        const { icon: Icon, label } = socialMeta[social.type]
        const external = social.type !== 'email'

        return (
          <li key={`${social.type}-${social.href}`}>
            <a
              href={socialHref(social.type, social.href)}
              target={external ? '_blank' : undefined}
              rel={external ? 'noreferrer' : undefined}
              aria-label={`${label} de ${member.name}`}
              className={cn(
                'flex h-9 w-9 items-center justify-center rounded-full transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring',
                tone === 'inverted'
                  ? 'bg-white/15 text-white backdrop-blur hover:bg-primary'
                  : 'bg-muted text-muted-foreground hover:bg-primary hover:text-primary-foreground',
              )}
            >
              <Icon className="h-4 w-4" aria-hidden />
            </a>
          </li>
        )
      })}
    </ul>
  )
}

function OverlayCard({ member }: { member: TeamSectionMember }) {
  return (
    <article className="group relative aspect-[3/4] overflow-hidden rounded-3xl bg-muted">
      <Image
        src={member.image.src}
        alt={member.image.alt ?? member.name}
        fill
        className="object-cover transition duration-700 group-hover:scale-105"
        sizes="(min-width: 1024px) 25vw, (min-width: 640px) 50vw, 100vw"
      />
      <div className="absolute inset-0 bg-gradient-to-t from-black/85 via-black/20 to-transparent transition-colors duration-500 md:group-focus-within:from-primary/90 md:group-hover:from-primary/90" />
      <div className="absolute inset-x-0 bottom-0 p-6 text-white">
        <h3 className="text-xl font-bold">{member.name}</h3>
        <p className="text-sm font-medium text-white/80">{member.role}</p>
        <div className="grid transition-all duration-500 md:grid-rows-[0fr] md:opacity-0 md:group-focus-within:grid-rows-[1fr] md:group-focus-within:opacity-100 md:group-hover:grid-rows-[1fr] md:group-hover:opacity-100">
          <div className="min-h-0 overflow-hidden">
            {member.bio ? (
              <p className="mt-3 text-sm leading-6 text-white/85">{member.bio}</p>
            ) : null}
            <Socials member={member} tone="inverted" className="mt-4" />
          </div>
        </div>
      </div>
    </article>
  )
}

function CardsCard({ member }: { member: TeamSectionMember }) {
  return (
    <article className="group flex h-full flex-col overflow-hidden rounded-3xl border bg-card transition duration-300 hover:-translate-y-1 hover:border-primary/40 hover:shadow-xl">
      <div className="relative aspect-[4/5] overflow-hidden bg-muted">
        <Image
          src={member.image.src}
          alt={member.image.alt ?? member.name}
          fill
          className="object-cover transition duration-700 group-hover:scale-105"
          sizes="(min-width: 1024px) 25vw, (min-width: 640px) 50vw, 100vw"
        />
      </div>
      <div className="flex flex-1 flex-col p-6">
        <h3 className="text-lg font-semibold">{member.name}</h3>
        <p className="text-sm font-medium text-primary">{member.role}</p>
        {member.bio ? (
          <p className="mt-3 text-sm leading-6 text-muted-foreground">{member.bio}</p>
        ) : null}
        <Socials member={member} className="mt-auto pt-5" />
      </div>
    </article>
  )
}

function MinimalCard({ member }: { member: TeamSectionMember }) {
  return (
    <article className="group flex flex-col items-center text-center">
      <div className="relative aspect-square w-full max-w-44 overflow-hidden rounded-full bg-muted ring-4 ring-transparent ring-offset-4 ring-offset-background transition duration-300 group-hover:ring-primary">
        <Image
          src={member.image.src}
          alt={member.image.alt ?? member.name}
          fill
          className="object-cover transition duration-700 group-hover:scale-105"
          sizes="176px"
        />
      </div>
      <h3 className="mt-5 text-base font-semibold sm:text-lg">{member.name}</h3>
      <p className="text-sm text-muted-foreground">{member.role}</p>
      <Socials member={member} className="mt-3 justify-center" />
    </article>
  )
}

function FeaturedMember({ member }: { member: TeamSectionMember }) {
  return (
    <article className="grid overflow-hidden rounded-3xl border bg-card md:grid-cols-2">
      <div className="relative aspect-[4/3] bg-muted md:aspect-auto md:min-h-[26rem]">
        <Image
          src={member.image.src}
          alt={member.image.alt ?? member.name}
          fill
          className="object-cover"
          sizes="(min-width: 768px) 50vw, 100vw"
        />
      </div>
      <div className="flex flex-col justify-center p-6 sm:p-8 md:p-12">
        <p className="text-sm font-semibold uppercase tracking-widest text-primary">
          {member.role}
        </p>
        <h3 className="mt-2 text-2xl font-bold tracking-tight md:text-3xl">{member.name}</h3>
        {member.bio ? <p className="mt-4 leading-7 text-muted-foreground">{member.bio}</p> : null}
        <Socials member={member} className="mt-6" />
      </div>
    </article>
  )
}

const cardByVariant = {
  overlay: OverlayCard,
  cards: CardsCard,
  minimal: MinimalCard,
  featured: CardsCard,
}

export function TeamSection({
  title,
  eyebrow,
  description,
  members,
  variant = 'overlay',
  columns = 4,
  action,
  className,
}: TeamSectionProps) {
  const reduceMotion = useReducedMotion()
  const [leader, ...rest] = members
  const list = variant === 'featured' ? rest : members
  const Card = cardByVariant[variant]

  return (
    <section className={cn('py-16 md:py-24', className)}>
      <div className="container">
        <div className="mx-auto max-w-2xl text-center">
          {eyebrow ? (
            <p className="text-sm font-semibold uppercase tracking-widest text-primary">
              {eyebrow}
            </p>
          ) : null}
          <h2 className="mt-2 text-3xl font-bold tracking-tight md:text-4xl lg:text-5xl">
            {title}
          </h2>
          {description ? (
            <p className="mt-4 text-lg leading-8 text-muted-foreground">{description}</p>
          ) : null}
        </div>

        {variant === 'featured' && leader ? (
          <motion.div
            className="mt-12"
            initial={reduceMotion ? false : { opacity: 0, y: 32 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true, amount: 0.2 }}
            transition={{ duration: 0.5 }}
          >
            <FeaturedMember member={leader} />
          </motion.div>
        ) : null}

        {list.length ? (
          <ul
            className={cn(
              'mt-12 grid gap-6',
              variant === 'minimal' ? 'grid-cols-2 gap-y-10' : '',
              columnClasses[columns],
            )}
          >
            {list.map((member, index) => (
              <motion.li
                key={member.name}
                initial={reduceMotion ? false : { opacity: 0, y: 32 }}
                whileInView={{ opacity: 1, y: 0 }}
                viewport={{ once: true, amount: 0.2 }}
                transition={{ duration: 0.5, delay: (index % columns) * 0.08 }}
              >
                <Card member={member} />
              </motion.li>
            ))}
          </ul>
        ) : null}

        {action ? (
          <div className="mt-12 flex justify-center">
            <Button asChild size="lg">
              <Link href={action.href}>{action.label}</Link>
            </Button>
          </div>
        ) : null}
      </div>
    </section>
  )
}

import Image from 'next/image'
import Link from 'next/link'
import { Button } from '@/components/ui/button'
import { cn } from '@/lib/utils'

export type CTABannerProps = {
  title: string
  description?: string
  primaryAction: { label: string; href: string }
  secondaryAction?: { label: string; href: string }
  backgroundImage?: { src: string; alt?: string }
  className?: string
}

export function CTABanner({
  title,
  description,
  primaryAction,
  secondaryAction,
  backgroundImage,
  className,
}: CTABannerProps) {
  return (
    <section
      className={cn(
        'relative isolate overflow-hidden bg-primary py-16 text-primary-foreground md:py-20',
        className,
      )}
      aria-labelledby="cta-banner-title"
    >
      {backgroundImage ? (
        <Image
          src={backgroundImage.src}
          alt={backgroundImage.alt ?? ''}
          fill
          className="-z-20 object-cover opacity-25"
          sizes="100vw"
        />
      ) : null}
      {backgroundImage ? <div className="absolute inset-0 -z-10 bg-primary/80" /> : null}
      <div className="container text-center">
        <h2
          id="cta-banner-title"
          className="mx-auto max-w-3xl text-3xl font-bold tracking-tight md:text-5xl"
        >
          {title}
        </h2>
        {description ? (
          <p className="mx-auto mt-5 max-w-2xl text-lg opacity-85">{description}</p>
        ) : null}
        <div className="mt-8 flex flex-wrap justify-center gap-3">
          <Button asChild size="lg" variant="secondary">
            <Link href={primaryAction.href}>{primaryAction.label}</Link>
          </Button>
          {secondaryAction ? (
            <Button
              asChild
              size="lg"
              variant="outline"
              className="border-current bg-transparent text-current hover:bg-white/10 hover:text-current"
            >
              <Link href={secondaryAction.href}>{secondaryAction.label}</Link>
            </Button>
          ) : null}
        </div>
      </div>
    </section>
  )
}

'use client'

import { useId, useState } from 'react'
import { ChevronDown } from 'lucide-react'

import { EyebrowHeading } from '@/components/library/primitives/EyebrowHeading'
import { getAccentTone, type AccentTone } from '@/components/library/primitives/accentTones'
import { cn } from '@/lib/utils'

export type FAQBorderedItem = {
  question: string
  answer: string
}

export type FAQBorderedProps = {
  items: readonly FAQBorderedItem[]
  title?: string
  eyebrow?: string
  description?: string
  embedded?: boolean
  defaultOpenIndex?: number | null
  tone?: AccentTone
  className?: string
}

const answerBackgrounds: Record<AccentTone, string> = {
  glow: 'bg-[#121212]',
  industrial: 'bg-slate-50',
  'industrial-dark': 'bg-slate-950',
}

/** FAQ em bloco contornado com perguntas sobre fundo de painel e respostas expansíveis. */
export function FAQBordered({
  items,
  title,
  eyebrow = 'FAQ',
  description,
  embedded = false,
  defaultOpenIndex = 0,
  tone = 'glow',
  className,
}: FAQBorderedProps) {
  const t = getAccentTone(tone)
  const baseId = useId()
  const [active, setActive] = useState<number | null>(defaultOpenIndex)

  const list = (
    <div className={cn('divide-y border', t.divide, t.border, tone === 'glow' && 'rounded-md')}>
      {items.map((item, index) => {
        const isOpen = active === index
        const panelId = `${baseId}-${index}`
        return (
          <div key={item.question}>
            <h3>
              <button
                type="button"
                onClick={() => setActive(isOpen ? null : index)}
                className={cn(
                  'flex w-full items-center justify-between gap-4 px-5 py-5 text-left transition-colors sm:px-7',
                  t.panel,
                  t.panelHover,
                  t.focus,
                )}
                aria-expanded={isOpen}
                aria-controls={panelId}
              >
                <span className={cn('text-sm font-semibold tracking-wide sm:text-base', t.strong)}>
                  {item.question}
                </span>
                <ChevronDown
                  className={cn(
                    'h-5 w-5 shrink-0 transition-transform duration-300',
                    t.accent,
                    isOpen && 'rotate-180',
                  )}
                  aria-hidden
                />
              </button>
            </h3>
            <div
              id={panelId}
              role="region"
              className={cn(
                'grid transition-all duration-500 ease-out',
                isOpen ? 'grid-rows-[1fr] opacity-100' : 'grid-rows-[0fr] opacity-0',
              )}
            >
              <div className="overflow-hidden" aria-hidden={!isOpen}>
                <p
                  className={cn(
                    'px-5 py-5 text-sm leading-relaxed sm:px-7 sm:text-base',
                    answerBackgrounds[tone],
                    t.body,
                  )}
                >
                  {item.answer}
                </p>
              </div>
            </div>
          </div>
        )
      })}
    </div>
  )

  if (embedded) {
    return (
      <div className={className}>
        {title ? (
          <EyebrowHeading
            tone={tone}
            eyebrow={eyebrow}
            title={title}
            titleAs="h2"
            className="mb-6"
          />
        ) : null}
        {list}
      </div>
    )
  }

  return (
    <section className={cn(t.section, className)}>
      <div className="container py-14 lg:py-16">
        {title ? (
          <EyebrowHeading
            tone={tone}
            eyebrow={eyebrow}
            title={title}
            description={description}
            layout="split"
            className="mb-10 lg:mb-12"
          />
        ) : null}
        {list}
      </div>
    </section>
  )
}

import Image from 'next/image'

