const focus =
  'rounded-sm focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-foreground'

function ColumnTitle({ children }: { children: ReactNode }) {
